import java.util.*;
import java.io.*;

public class Main {
    static final int MAXN = 410;
    static final int MAXM = 200020;
    static final int INF = 0x3f3f3f3f;
    static final int[] dir = {-1, 0, 1, 0};
    static final int N = 12; // maximum grid size
    static char[][] grid = new char[N][N];
    static char[][] heat = new char[N][N];
    static int[][] distMap = new int[N][N];
    static int[][] timeMap = new int[N][N];
    static int n, t;
    static FlowNetwork net = new FlowNetwork();

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        n = Integer.parseInt(st.nextToken());
        t = Integer.parseInt(st.nextToken());

        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            grid[i] = line.toCharArray();
        }
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            heat[i] = line.toCharArray();
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] == 'Z') {
                    findObstacles(i, j);
                }
            }
        }

        int S = 0;
        int T = n * n * 2 + 1;
        net.initialize();

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > '0' && grid[i][j] <= '9') {
                    net.addEdge(S, i * n + j + 1, grid[i][j] - '0');
                }
                if (heat[i][j] > '0' && heat[i][j] <= '9') {
                    net.addEdge(n * n + i * n + j + 1, T, heat[i][j] - '0');
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 0; j < n; j++) {
                if (grid[i][j] > '0' && grid[i][j] <= '9') {
                    findHeatSources(i, j);
                    for (int x = 0; x < n; x++) {
                        for (int y = 0; y < n; y++) {
                            if (heat[x][y] > '0' && heat[x][y] <= '9' && distMap[x][y] <= t) {
                                net.addEdge(i * n + j + 1, n * n + x * n + y + 1, INF);
                            }
                        }
                    }
                }
            }
        }

        int res = net.maxFlow(S, T);
        System.out.println(res);
    }

    static void findObstacles(int sx, int sy) {
        for (int i = 0; i < n; i++) {
            Arrays.fill(timeMap[i], 0x3f);
        }
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{sx, sy});
        timeMap[sx][sy] = 0;
        while (!q.isEmpty()) {
            int[] pos = q.poll();
            int x = pos[0], y = pos[1];
            for (int i = 0; i < 4; i++) {
                int nx = x + dir[i];
                int ny = y + dir[i + 1];
                if (valid(nx, ny) && grid[nx][ny] >= '0' && grid[nx][ny] <= '9' && timeMap[nx][ny] > timeMap[x][y] + 1) {
                    timeMap[nx][ny] = timeMap[x][y] + 1;
                    q.offer(new int[]{nx, ny});
                }
            }
        }
    }

    static void findHeatSources(int sx, int sy) {
        for (int i = 0; i < n; i++) {
            Arrays.fill(distMap[i], 0x3f);
        }
        Queue<int[]> q = new LinkedList<>();
        q.offer(new int[]{sx, sy});
        distMap[sx][sy] = 0;
        while (!q.isEmpty()) {
            int[] pos = q.poll();
            int x = pos[0], y = pos[1];
            for (int i = 0; i < 4; i++) {
                int nx = x + dir[i];
                int ny = y + dir[i + 1];
                if (valid(nx, ny) && heat[nx][ny] >= '0' && heat[nx][ny] <= '9' && distMap[nx][ny] > distMap[x][y] + 1) {
                    if (heat[nx][ny] >= '0' && timeMap[nx][ny] >= distMap[x][y] + 1) {
                        distMap[nx][ny] = distMap[x][y] + 1;
                        if (timeMap[nx][ny] > distMap[nx][ny]) {
                            q.offer(new int[]{nx, ny});
                        }
                    }
                }
            }
        }
    }

    static boolean valid(int x, int y) {
        return x >= 0 && x < n && y >= 0 && y < n;
    }

    static class FlowNetwork {
        int[] head = new int[MAXN];
        int[] v = new int[MAXM];
        int[] nxt = new int[MAXM];
        int[] capacity = new int[MAXM];
        int[] flow = new int[MAXM];
        int[] current = new int[MAXN];
        int edgeCount;
        int source, sink;
        int[] dist = new int[MAXN];

        void initialize() {
            Arrays.fill(head, -1);
            edgeCount = 0;
        }

        void addEdge(int u, int v, int c) {
            this.v[edgeCount] = v;
            this.nxt[edgeCount] = head[u];
            this.capacity[edgeCount] = c;
            this.flow[edgeCount] = 0;
            head[u] = edgeCount++;
            this.v[edgeCount] = u;
            this.nxt[edgeCount] = head[v];
            this.capacity[edgeCount] = 0;
            this.flow[edgeCount] = 0;
            head[v] = edgeCount++;
        }

        boolean buildLevelGraph() {
            Arrays.fill(dist, -1);
            dist[source] = 0;
            Queue<Integer> q = new LinkedList<>();
            q.offer(source);
            while (!q.isEmpty()) {
                int u = q.poll();
                for (int i = head[u]; i != -1; i = nxt[i]) {
                    int v = this.v[i];
                    if (dist[v] == -1 && capacity[i] > flow[i]) {
                        dist[v] = dist[u] + 1;
                        q.offer(v);
                    }
                }
            }
            return dist[sink] != -1;
        }

        int sendFlow(int u, int flowIn) {
            if (u == sink || flowIn == 0) return flowIn;
            int totalFlow = 0;
            for (int i = current[u]; i != -1; i = nxt[i]) {
                int v = this.v[i];
                if (dist[v] == dist[u] + 1 && (pushed = sendFlow(v, Math.min(flowIn, capacity[i] - flow[i]))) > 0) {
                    flow[i] += pushed;
                    flow[i ^ 1] -= pushed;
                    flowIn -= pushed;
                    totalFlow += pushed;
                    if (flowIn == 0) break;
                }
            }
            return totalFlow;
        }

        int maxFlow(int s, int t) {
            source = s;
            sink = t;
            int total = 0;
            while (buildLevelGraph()) {
                for (int i = 0; i < current.length; i++) {
                    current[i] = head[i];
                }
                int pushed;
                while ((pushed = sendFlow(source, INF)) > 0) {
                    total += pushed;
                }
            }
            return total;
        }
    }
